var i=204;var s=`204-fruit-fillings-compotes-and-dessert-sauces`;var a=`191`;var r={en:`Fruit Fillings, Compotes, and Dessert Sauces`,ua:`Фруктові начинки, компоти та десертні соуси`};var n={short:`Fruit fillings, compotes and dessert sauces turn fruit into components with controlled sweetness, acidity, thickness and texture. The method varies with fruit ripeness, pectin content, water content and whether the result must stay fluid or hold its shape.`,sections:[{title:`Core idea`,text:`A compote cooks cut fruit gently in its own juice or a small amount of liquid so pieces remain recognizable. A coulis is usually a smooth fruit purée or sauce, sometimes strained; a pastry filling must also resist leaking or excessive migration into baked layers.`},{title:`Scientific / practical principles`,text:`Heat softens plant cell walls and releases water. Sugar binds water and affects perceived acidity; pectin and starch thicken differently. Naturally pectin-rich fruit may need less thickener, while juicy berries can make a pie filling runny unless the recipe's thickening method accounts for their liquid.`},{title:`How to apply it`,text:`Choose fruit by ripeness and intended texture. For compote, add only enough liquid to avoid scorching and stop before pieces disintegrate. For coulis, purée and strain if a smooth texture is needed. For fillings, use a tested starch or pectin ratio and cool before assembling pastries.`},{title:`Practical example`,text:`Divide the same berries between a gently cooked chunky compote and a puréed, strained sauce. Measure cooked yield and compare viscosity, acidity, mouthfeel and behavior on chilled cheesecake.`},{title:`Common mistakes and limitations`,text:`Boiling too vigorously breaks delicate fruit; hot filling can melt pastry fat or collapse creams; arbitrary sugar reduction changes both flavor and preservation properties. A thickened fruit sauce is not automatically a shelf-stable preserve; refrigerate unless processed by a tested canning formula.`},{title:`Related theories`,text:`60, 201, 202, 205.`}]};var o={short:`Фруктові начинки, компоти та десертні соуси перетворюють фрукти на компоненти з контрольованими солодкістю, кислотністю, густотою й текстурою. Метод залежить від стиглості фруктів, кількості води й пектину та бажаної форми подачі.`,sections:[{title:`Суть`,text:`Компот готують із нарізаних фруктів у власному соку або невеликій кількості рідини так, щоб шматочки частково зберігали форму. Кулі: зазвичай гладке фруктове пюре або соус, інколи проціджений; начинка для випічки має ще й не витікати та не надмірно зволожувати основу.`},{title:`Наукові та практичні принципи`,text:`Нагрівання розм’якшує клітинні стінки й вивільняє воду. Цукор зв’язує частину води та змінює відчуття кислотності, а пектин і крохмаль загущують різними механізмами. Соковиті ягоди можуть давати рідку начинку, якщо не врахувати їхню вологість.`},{title:`Як застосувати`,text:`Обирайте фрукти за стиглістю та потрібною текстурою. Для компоту додавайте мінімум рідини й зупиняйте нагрівання до руйнування шматочків. Для гладкого соусу подрібнюйте й за потреби проціджуйте. Для начинки дотримуйтеся перевіреного співвідношення загусника та охолоджуйте її перед складанням десерту.`},{title:`Практичний дослід`,text:`З одних і тих самих ягід приготуйте густіший компот зі шматочками й однорідний проціджений соус. Порівняйте вихід, в’язкість, кислотність і поведінку на охолодженому чизкейку.`},{title:`Поширені помилки й обмеження`,text:`Сильне кипіння руйнує ніжні фрукти, гаряча начинка може розтопити жир у тісті або зіпсувати крем, а довільне зменшення цукру змінює смак і здатність до зберігання. Загущений соус не є автоматично консервами тривалого зберігання; охолоджуйте його, якщо не використано перевірену технологію.`},{title:`Пов’язані теорії`,text:`60, 201, 202, 205.`}]};var l=[201,202,205];var c=`References / Джерела`;var d=[`https://nchfp.uga.edu/how/make-jam-jelly`,`https://www.kingarthurbaking.com/learn/guides/cake`,`https://extension.umn.edu/preserving-and-preparing/making-jams-and-jellies`,`https://www.kingarthurbaking.com/learn/cake`];var u={id:204,slug:s,group:`191`,title:r,en:n,ua:o,related:l,referenceTitle:c,references:d};export{u as default,n as en,a as group,i as id,c as referenceTitle,d as references,l as related,s as slug,r as title,o as ua};